'use strict';
const R=10,original=new Set(['fixed_armor_or_spike','vertical_armor_slider','warning_drop_spike','spring_wall']);
function visibleGeometry(obs,laserAbove){for(const id of laserAbove)if(!obs.obstacles.some(o=>o.id===id))laserAbove.delete(id);for(const o of obs.obstacles){const b=o.bounds;if(o.kind==='laser_scanner'&&b&&b.minY>=100&&b.maxX-b.minX>=b.maxY-b.minY&&obs.player.vy< -300&&obs.player.y-obs.player.vy**2/(2*820)<=b.minY-10-(o.width||0)/2)laserAbove.add(o.id);}if(obs.obstacles.every(o=>original.has(o.kind)))return obs;return{...obs,obstacles:obs.obstacles.map(o=>{if(o.kind==='crack_bumper_panel'&&o.status==='active')return{...o,kind:'spring_wall'};if(original.has(o.kind)||!o.lethal)return o;const b=o.bounds||{minX:o.x,maxX:o.x+o.w,minY:o.y,maxY:o.y+o.h},above=laserAbove.has(o.id)||(b.minY+b.maxY)/2>=270;return{...o,x:b.minX,w:b.maxX-b.minX,y:above?b.minY:-120,h:above?540-b.minY:b.maxY+120};})};}
function target(obs){const p=obs.player,rs=obs.obstacles.filter(o=>o.lethal&&o.kind!=='warning_drop_spike'&&o.x+o.w>=p.x-R);if(!rs.length)return 270;const x=Math.min(...rs.map(o=>o.x)),pair=rs.filter(o=>Math.abs(o.x-x)<5);let top=10,bottom=530;for(const o of pair)if(o.y<0)top=Math.max(top,o.y+o.h+R+8);else bottom=Math.min(bottom,o.y-R-8);return(top+bottom)/2;}
function create(saved){if(saved&&(!['visible-geometry-reactive-v5','visible-geometry-reactive-v6'].includes(saved.version)||!Array.isArray(saved.launched)||saved.launched.length>40||saved.launched.some(x=>typeof x!=='string'||x.length>100)))throw Error('Invalid controller checkpoint');if(saved?.laserAbove&&(!Array.isArray(saved.laserAbove)||saved.laserAbove.length>40||saved.laserAbove.some(x=>typeof x!=='string'||x.length>100)))throw Error('Invalid laser lane checkpoint');const launched=new Set(saved?.launched||[]),laserAbove=new Set(saved?.laserAbove||[]);function act(input){const obs=visibleGeometry(input,laserAbove),p=obs.player;let center=target(obs),pad=obs.obstacles.find(o=>o.kind==='spring_wall'&&!launched.has(o.id)&&o.x+o.w>=p.x-R&&o.x-p.x<200);if(pad&&p.vy< -300&&p.x>=pad.x-R)launched.add(pad.id);if(pad&&launched.has(pad.id))pad=null;const priorGate=pad&&obs.obstacles.some(o=>o.lethal&&o.kind!=='warning_drop_spike'&&o.x<pad.x&&o.x+o.w>=p.x-R);if(pad&&!priorGate)center=pad.y;else{const drop=obs.obstacles.find(o=>o.kind==='warning_drop_spike'&&['warning','falling'].includes(o.status)&&o.x+o.w>=p.x-R&&o.x-p.x<240);if(drop)center-=60;}return p.y>center+20&&p.vy>0;}act.snapshot=()=>({version:'visible-geometry-reactive-v6',launched:[...launched],laserAbove:[...laserAbove]});return act;}
module.exports={create,target,id:'visible-geometry-reactive-v6',observationScope:'current visible geometry/status/player only; serializable observed-launch and reachable above-beam lane memory'};
